INSERT INTO public.changelog_entries (title, description) VALUES
  ('ملاحظات ثابتة قابلة للتعديل بعرض السعر', 'صار فيه خانة "الملاحظات الثابتة" بنموذج إنشاء/تعديل عرض السعر — نفس النقاط اللي كانت تطبع ثابتة تحت كل عرض، بس هلأ قابلة للتعديل أو الحذف لكل عرض على حدة.'),
  ('المساعد الذكي جنب الشات الجماعي وقابل للسحب', 'أيقونة المساعد الذكي انتقلت جنب أيقونة الشات الجماعي، وصارت قابلة للسحب والإفلات لأي مكان بالشاشة زي أيقونة الشات تماماً.'),
  ('إصلاح: زر إجراء ما عاد ينقص تحت الشاشة', 'زر "⚡ إجراء" (بعروض الأسعار وغيرها) صار يفتح لفوق تلقائياً لو ما في مساحة كافية تحته — بدل ما ينقص جزء منه بآخر صف بجدول طويل.'),
  ('إصلاح: اختفاء قائمة الكتب الرسمية بعد الحفظ', 'حفظ تعديل على كتاب رسمي ما عاد يخلي القائمة تختفي — وفكّ قفل كتاب بكلمة سر ضل محفوظ بدون ما تحتاج تدخلها من جديد كل مرة.');
